import { useId } from 'react'
import geo from './logo-geometry.json'

const f = (n) => +n.toFixed(1)

/**
 * The lotru wordmark: Fredoka letters with the ring of light as the "o".
 * Generated by brand/build_logo.py — edit that script, not the geometry.
 * Letters use currentColor; the ring keeps its gradient.
 */
export default function Logo({ title = 'Lotru', className }) {
  const uid = useId().replace(/:/g, '')
  const [x, y, w, h] = geo.viewBox
  const { cx, cy, r, stroke } = geo.ring

  return (
    <svg className={className} viewBox={geo.viewBox.join(' ')} role="img" aria-label={title}>
      <defs>
        {/* Knock the letters out around the ring so it sits cleanly in front of them. */}
        <mask id={`${uid}k`} maskUnits="userSpaceOnUse" x={x} y={y} width={w} height={h}>
          <rect x={x} y={y} width={w} height={h} fill="#fff" />
          <circle cx={cx} cy={cy} r={geo.knockoutRadius} fill="#000" />
        </mask>
        <mask id={`${uid}r`} maskUnits="userSpaceOnUse" x={x} y={y} width={w} height={h}>
          <circle cx={cx} cy={cy} r={r} fill="none" stroke="#fff" strokeWidth={stroke} />
        </mask>
        {geo.arcs.map((a, i) => (
          <linearGradient
            key={i}
            id={`${uid}g${i}`}
            gradientUnits="userSpaceOnUse"
            x1={a.from[0]}
            y1={a.from[1]}
            x2={a.to[0]}
            y2={a.to[1]}
          >
            <stop offset="0" stopColor={a.c0} />
            <stop offset="1" stopColor={a.c1} />
          </linearGradient>
        ))}
      </defs>

      <path
        d={geo.letters}
        fill="currentColor"
        {...(geo.letterSoften
          ? { stroke: 'currentColor', strokeWidth: geo.letterSoften, strokeLinejoin: 'round' }
          : {})}
        mask={`url(#${uid}k)`}
      />
      <g mask={`url(#${uid}r)`} fill="none" strokeWidth={f(stroke * 1.6)}>
        {geo.arcs.map((a, i) => (
          <path
            key={i}
            d={`M${a.from[0]} ${a.from[1]}A${r} ${r} 0 0 1 ${a.end[0]} ${a.end[1]}`}
            stroke={`url(#${uid}g${i})`}
          />
        ))}
      </g>
    </svg>
  )
}
